\begin{tabular}{@{}llccc@{}}
\toprule
Condition & Configuration & Entropy (final) & Collapses? & Test Acc \\
\midrule
A & Unfrozen + InstanceNorm2d & $1.475 \pm 0.021$ & No & $0.919$ \\
B & Frozen + InstanceNorm2d   & $0.992 \pm 0.041$ & No & $0.577$ \\
C & Unfrozen + No norm        & $\mathbf{0.184 \pm 0.260}$ & \textbf{Yes} & $0.921$ \\
